+template <class T>
+inline T GetBesselZero(const T& x) {
+  T abx = fabs(x);
+
+  if (abx < 3.75) {
+    T t = abx / 3.75;
+    T p =
+        1.0 +
+        t * t *
+            (3.5156229 +
+             t * t * (3.0899424 + t * t * (1.2067492 + t * t * (0.2659732 + t * t * (0.0360768 + t * t * 0.0045813)))));
+    return log(p);
+  } else {
+    T t = 3.75 / abx;
+
+    T poly =
+        0.39894228 +
+        t * (0.01328592 +
+             t * (0.00225319 +
+                  t * (-0.00157565 +
+                       t * (0.00916281 + t * (-0.02057706 + t * (0.02635537 + t * (-0.01647633 + t * 0.00392377)))))));
+
+    T arg = sqrt(abx) * poly;
+    return abx - log(arg);
